const D = { energy:.6, scale:1, density:.55, speed:1, hue:24, x:.5, y:.5, tilt:.5, style:'poured', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const hs = n => { const s = Math.sin(n*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const vn = (x,y) => { const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hs(ix*57.3+iy*131.9), b=hs((ix+1)*57.3+iy*131.9), c=hs(ix*57.3+(iy+1)*131.9), d=hs((ix+1)*57.3+(iy+1)*131.9);
  return a + (b-a)*wx + (c-a)*wy + (a-b-c+d)*wx*wy; };
const fbm = (x,y) => .60*vn(x,y) + .26*vn(x*2.1+4.7, y*2.1-2.3) + .14*vn(x*4.3-1.1, y*4.3+5.9);

const sty = P.style;
const plan = (sty==='plan'), paper = (sty==='engraving'), hier = (sty==='hierarchy'), lac = (sty==='lacquer');
const H = ((P.hue%360)+360)%360;

// ---- the chair / L-tromino rep-4 substitution -------------------------------
// A tile is (x, y, s, m): axis-aligned box [x, x+2s] x [y, y+2s] with the
// quarter `m` missing.  Corner ids: 0=BL 1=BR 2=TL 3=TR.
// Doubling the L gives a 4x4 box less a 2x2 quarter = exactly 4 half-size Ls.
const OUT = [
  [[1,0],[2,0],[2,2],[0,2],[0,1],[1,1]],   // m=0, bottom-left quarter missing
  [[0,0],[1,0],[1,1],[2,1],[2,2],[0,2]],   // m=1, bottom-right
  [[0,0],[2,0],[2,2],[1,2],[1,1],[0,1]],   // m=2, top-left
  [[0,0],[2,0],[2,1],[1,1],[1,2],[0,2]]    // m=3, top-right
];
const RC = [1,3,0,2];                       // 90deg CCW maps corner -> corner
const KOF = [2,3,1,0];                      // rotations taking the m=3 rule to m
// children of an m=3 parent, in the parent's local [0,4]^2 frame (half-box 1)
const BASE = [[1,1,3],[3,1,2],[1,3,1],[2,2,3]];

// ---- motion ----------------------------------------------------------------
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
const rate = P.speed*(.45 + .5*K.intensity);
S.px = (S.px||0) + dt*rate*.052;
S.py = (S.py||0) + dt*rate*.031;
const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
const glow = (.40 + .60*P.energy)*(.55 + .5*K.intensity) + bass*.3;
// the substitution depth BREATHES on incommensurate rates — tiles resolve and re-merge
const wob = .55*Math.sin(K.t*.067) + .30*Math.sin(K.t*.151+1.4) + .15*Math.sin(K.t*.373+2.7);
const LVf = cl(1.15 + cl(P.density,0,1)*2.9 + 1.15*P.energy*wob, 1.02, 4.42);
const rot = cl(P.tilt,0,1)*(K.t*.0125 + .10*Math.sin(K.t*.053+.9) + .045*Math.sin(K.t*.139+2.2));
const ca = Math.cos(rot), sa = Math.sin(rot);

// ---- lattice: a 3x2 rectangle holds exactly two L-trominoes ---------------
const SU = u*.30*cl(P.scale,.3,2.2);        // px per unit cell
// leaf budget: visible lattice area / leaf area (3*4^-D) must stay under ~460
const budD = Math.floor(Math.log(Math.max(1.0001, 460*3*SU*SU/(width*height)))/Math.log(4));
const Dw = Math.max(1, Math.min(Math.floor(LVf), budD));
const frac = (Dw === Math.floor(LVf)) ? (LVf - Dw) : 1;
const ox = cl(P.x,.1,.9)*width, oy = cl(P.y,.1,.9)*height;
const pX = S.px, pY = S.py;
const TS = (lx,ly) => { const rx = lx - pX, ry = ly - pY;
  return [ox + (rx*ca - ry*sa)*SU, oy + (rx*sa + ry*ca)*SU]; };
const IV = (sx,sy) => { const dx=(sx-ox)/SU, dy=(sy-oy)/SU;
  return [dx*ca + dy*sa + pX, -dx*sa + dy*ca + pY]; };

// ---- palette ----------------------------------------------------------------
let GC;
if (plan)       GC = [212,64,19];
else if (paper) GC = [40,10,86];
else if (hier)  GC = [H,44,7];
else if (lac)   GC = [H,34,8];
else            GC = [H,14,12];
noStroke(); fill(GC[0],GC[1],GC[2],100); rect(0,0,width,height);

const cs = [IV(0,0), IV(width,0), IV(0,height), IV(width,height)];
let mnx=1e9, mxx=-1e9, mny=1e9, mxy=-1e9;
for (let i=0;i<4;i++){ mnx=Math.min(mnx,cs[i][0]); mxx=Math.max(mxx,cs[i][0]);
                       mny=Math.min(mny,cs[i][1]); mxy=Math.max(mxy,cs[i][1]); }
const drift = K.t*.031;

const lerpH = (a,b,t) => { const d = ((b - a + 540)%360) - 180; return ((a + d*t)%360+360)%360; };
function tone(m, acc, fv){
  if (plan)  return [212, 58, cl(15 + 9*m + 10*fv, 8, 38)];
  if (paper) return [40, 7, cl(94 - 9*m - 16*fv, 42, 97)];
  // `acc` is the substitution PATH folded with a geometric weight, so siblings
  // cluster and the whole inflation hierarchy shows as nested colour families
  if (hier)  return [(((H + acc*46 + fv*22)%360)+360)%360, cl(40 + 40*fv, 8, 92), cl(18 + 58*(.5 + .09*acc) + 14*fv, 5, 92)];
  if (lac)   return [(H + m*38 + fv*22) % 360, cl(58 + 24*fv, 18, 92), cl(26 + 52*fv + 14*m, 10, 90)];
  const shade = [.86,.50,.66,.38][m];       // poured: four castings
  return [(H + fv*16 - 6) % 360, cl(10 + 9*fv, 2, 26), cl(22 + 48*shade + 16*fv, 8, 88)];
}

// ---- draw one tile, or recurse -------------------------------------------
function draw1(x, y, s, m, dep, acc, pm, pacc){
  // bbox cull in lattice space (conservative: use the full 2s box)
  if (x + 2*s < mnx - .1 || x > mxx + .1 || y + 2*s < mny - .1 || y > mxy + .1) return;
  if (dep < Dw){
    const k = KOF[m];
    for (let i=0;i<4;i++){
      let lx = BASE[i][0], ly = BASE[i][1], mm = BASE[i][2];
      for (let r=0;r<k;r++){ const t2 = 4 - ly; ly = lx; lx = t2; mm = RC[mm]; }
      const cxw = x + lx*(s*.5), cyw = y + ly*(s*.5);      // child centre, world
      draw1(cxw - s*.5, cyw - s*.5, s*.5, mm, dep+1, acc + (i - 1.5)*Math.pow(.6, dep), m, acc);
    }
    if (dep >= 2) return;                                   // structural outlines: top 2 levels
  }
  const O = OUT[m], pj = [];
  let gx=0, gy=0;
  for (let v=0;v<6;v++){ const wx = x + O[v][0]*s, wy = y + O[v][1]*s;
    gx+=wx; gy+=wy; pj.push(TS(wx,wy)); }
  gx/=6; gy/=6;
  if (dep < Dw){                                            // structural (coarse) outline
    noFill();
    stroke(plan?196:(paper?28:H), plan?26:(paper?26:14), plan?100:(paper?12:(hier?96:92)),
           cl(30 + 46*glow*(1 - dep/Math.max(1,Dw)), 0, 80));
    strokeWeight(Math.max(1.2, SU*s*.055));
    beginShape(); for (let v=0;v<6;v++) vertex(pj[v][0], pj[v][1]); endShape(CLOSE);
    return;
  }
  // leaf: fade from the PARENT's tone to its own as the level resolves, so a
  // depth change never pops the frame
  const fv = fbm(gx*.17 + drift*.6, gy*.17 - drift*.37);
  const c0 = tone(m, acc, fv), c1 = tone(pm, pacc, fv);
  const c = [lerpH(c1[0], c0[0], frac), c1[1] + (c0[1]-c1[1])*frac, c1[2] + (c0[2]-c1[2])*frac];
  if (paper || plan) noFill(); else fill(c[0], c[1], c[2], 100);
  stroke(plan?196:(paper?28:H), plan?26:(paper?28:(lac?36:12)), plan?100:(paper?12:(hier?98:8)),
         cl((plan||paper?36:18) + 58*frac, 0, 96));
  strokeWeight(Math.max(.9, SU*s*.05));
  beginShape(); for (let v=0;v<6;v++) vertex(pj[v][0], pj[v][1]); endShape(CLOSE);
  if (paper){                                               // engraved hatching by orientation
    const nh = 2 + m;
    stroke(28, 28, 12, 30); strokeWeight(Math.max(.7, SU*s*.02)); noFill();
    for (let i=1;i<=nh;i++){ const q = i/(nh+1);
      const a2 = pj[0], b2 = pj[3], c2 = pj[1], d2 = pj[4];
      line(a2[0]+(c2[0]-a2[0])*q, a2[1]+(c2[1]-a2[1])*q, b2[0]+(d2[0]-b2[0])*q, b2[1]+(d2[1]-b2[1])*q);
    }
  }
}

// ---- top layer: a 3x2 rect is tiled by two Ls, two ways — seeded per rect
// cfgA = L(box[X,X+2], m=3) + L(box[X+1,X+3], m=0)
// cfgB = L(box[X,X+2], m=1) + L(box[X+1,X+3], m=2)   (both verified exact)
const a0 = Math.floor((mnx - 3)/3), a1 = Math.ceil(mxx/3);
const b0 = Math.floor((mny - 2)/2), b1 = Math.ceil(mxy/2);
for (let b=b0; b<=b1; b++){
  for (let a=a0; a<=a1; a++){
    const X = a*3, Y = b*2, cfg = hs(a*7.3 + b*3.1 + 1.7) > .5;
    draw1(X + 0, Y, 1, cfg ? 1 : 3, 0, -0.5, cfg ? 1 : 3, -0.5);
    draw1(X + 1, Y, 1, cfg ? 2 : 0, 0,  0.5, cfg ? 2 : 0,  0.5);
  }
}

// ---- a light crawling the hierarchy, out of phase with the breathing -------
if (!plan && !paper){
  push(); blendMode(ADD); noStroke();
  const lxx = ox + Math.cos(K.t*.079 + .8)*width*.40 + Math.cos(K.t*.197)*width*.11;
  const lyy = oy + Math.sin(K.t*.113 + 2.1)*height*.38 + Math.sin(K.t*.293+1)*height*.10;
  for (let i=5;i>=1;i--){ fill(H, hier?26:20, 100, 1.3 + 2.5*glow); ellipse(lxx, lyy, u*.19*i, u*.19*i); }
  pop(); blendMode(BLEND);
}
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
